const DATE_PATTERN = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;
const MONTH_LENGTHS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
const MONTH_OFFSETS = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
const MAX_YEAR_EXCLUSIVE = 10000;

function isLeapYear(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function daysBeforeYear(year) {
  return (
    year * 365 +
    Math.floor((year + 3) / 4) -
    Math.floor((year + 99) / 100) +
    Math.floor((year + 399) / 400)
  );
}

function ordinalFromParts(year, month, day) {
  return (
    daysBeforeYear(year) +
    MONTH_OFFSETS[month - 1] +
    (month > 2 && isLeapYear(year) ? 1 : 0) +
    day -
    1
  );
}

const MAX_ORDINAL_EXCLUSIVE = daysBeforeYear(MAX_YEAR_EXCLUSIVE);
const REFERENCE_ORDINAL = ordinalFromParts(1970, 1, 1);

function parseDateOrdinal(value) {
  if (typeof value !== "string" || value.length !== 10) {
    throw new RangeError("Invalid calendar date");
  }

  const match = DATE_PATTERN.exec(value);
  if (match === null) {
    throw new RangeError("Invalid calendar date");
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  if (month < 1 || month > 12) {
    throw new RangeError("Invalid calendar date");
  }

  let maximumDay = MONTH_LENGTHS[month - 1];
  if (month === 2 && isLeapYear(year)) {
    maximumDay = 29;
  }

  if (day < 1 || day > maximumDay) {
    throw new RangeError("Invalid calendar date");
  }

  return ordinalFromParts(year, month, day);
}

function weekdayOfOrdinal(ordinal) {
  const raw = (ordinal - REFERENCE_ORDINAL + 4) % 7;
  return (raw + 7) % 7;
}

function isWeekdayOrdinal(ordinal) {
  const weekday = weekdayOfOrdinal(ordinal);
  return weekday >= 1 && weekday <= 5;
}

function nextWeekdayAfter(ordinal) {
  let next = ordinal + 1;
  while (!isWeekdayOrdinal(next)) {
    next += 1;
  }
  return next;
}

function buildHolidayCalendar(holidays) {
  if (!Array.isArray(holidays)) {
    throw new RangeError("holidays must be an array");
  }

  const observed = new Set();
  const weekendHolidays = [];

  for (let index = 0; index < holidays.length; index += 1) {
    const ordinal = parseDateOrdinal(holidays[index]);

    if (isWeekdayOrdinal(ordinal)) {
      observed.add(ordinal);
    } else {
      weekendHolidays.push(ordinal);
    }
  }

  weekendHolidays.sort((a, b) => a - b);

  let lastWeekendObservation = null;

  for (const holiday of weekendHolidays) {
    const weekday = weekdayOfOrdinal(holiday);
    let candidate = holiday + (weekday === 6 ? 2 : 1);

    if (
      lastWeekendObservation !== null &&
      candidate <= lastWeekendObservation
    ) {
      candidate = nextWeekdayAfter(lastWeekendObservation);
    }

    while (observed.has(candidate)) {
      candidate = nextWeekdayAfter(candidate);
    }

    observed.add(candidate);
    lastWeekendObservation = candidate;
  }

  const orderedObserved = Array.from(observed).sort((a, b) => a - b);
  return { observed, orderedObserved };
}

function formatOrdinal(ordinal) {
  if (
    !Number.isInteger(ordinal) ||
    ordinal < 0 ||
    ordinal >= MAX_ORDINAL_EXCLUSIVE
  ) {
    throw new RangeError("Resulting date is outside YYYY-MM-DD range");
  }

  let lowYear = 0;
  let highYear = MAX_YEAR_EXCLUSIVE;

  while (lowYear + 1 < highYear) {
    const middle = Math.floor((lowYear + highYear) / 2);
    if (daysBeforeYear(middle) <= ordinal) {
      lowYear = middle;
    } else {
      highYear = middle;
    }
  }

  const year = lowYear;
  let dayOfYear = ordinal - daysBeforeYear(year);
  let month = 1;

  while (month <= 12) {
    let monthLength = MONTH_LENGTHS[month - 1];
    if (month === 2 && isLeapYear(year)) {
      monthLength = 29;
    }

    if (dayOfYear < monthLength) {
      break;
    }

    dayOfYear -= monthLength;
    month += 1;
  }

  const day = dayOfYear + 1;
  const yearText = String(year).padStart(4, "0");
  const monthText = String(month).padStart(2, "0");
  const dayText = String(day).padStart(2, "0");

  return `${yearText}-${monthText}-${dayText}`;
}

function lowerBound(values, target) {
  let low = 0;
  let high = values.length;

  while (low < high) {
    const middle = Math.floor((low + high) / 2);
    if (values[middle] < target) {
      low = middle + 1;
    } else {
      high = middle;
    }
  }

  return low;
}

function countBusinessDays(from, to, orderedObserved) {
  if (from >= to) {
    return 0;
  }

  const totalDays = to - from;
  const wholeWeeks = Math.floor(totalDays / 7);
  let count = wholeWeeks * 5;
  const remainderStart = from + wholeWeeks * 7;

  for (let ordinal = remainderStart; ordinal < to; ordinal += 1) {
    if (isWeekdayOrdinal(ordinal)) {
      count += 1;
    }
  }

  const observedCount =
    lowerBound(orderedObserved, to) - lowerBound(orderedObserved, from);

  return count - observedCount;
}

function isBusinessOrdinal(ordinal, observed) {
  return isWeekdayOrdinal(ordinal) && !observed.has(ordinal);
}

function throwResultOutOfRange() {
  throw new RangeError("Resulting date is outside YYYY-MM-DD range");
}

export function isBusinessDay(date, holidays = []) {
  const ordinal = parseDateOrdinal(date);
  const calendar = buildHolidayCalendar(holidays);
  return isBusinessOrdinal(ordinal, calendar.observed);
}

export function addBusinessDays(date, n, holidays = []) {
  const start = parseDateOrdinal(date);

  if (!Number.isInteger(n)) {
    throw new RangeError("n must be an integer");
  }

  const calendar = buildHolidayCalendar(holidays);
  const orderedObserved = calendar.orderedObserved;

  if (n === 0) {
    if (isBusinessOrdinal(start, calendar.observed)) {
      return formatOrdinal(start);
    }

    if (countBusinessDays(start, MAX_ORDINAL_EXCLUSIVE, orderedObserved) < 1) {
      throwResultOutOfRange();
    }

    let low = start;
    let high = MAX_ORDINAL_EXCLUSIVE - 1;

    while (low < high) {
      const middle = Math.floor((low + high) / 2);
      if (countBusinessDays(start, middle + 1, orderedObserved) >= 1) {
        high = middle;
      } else {
        low = middle + 1;
      }
    }

    return formatOrdinal(low);
  }

  if (n > 0) {
    const firstPossible = start + 1;
    const available = countBusinessDays(
      firstPossible,
      MAX_ORDINAL_EXCLUSIVE,
      orderedObserved,
    );

    if (n > available) {
      throwResultOutOfRange();
    }

    let low = firstPossible;
    let high = MAX_ORDINAL_EXCLUSIVE - 1;

    while (low < high) {
      const middle = Math.floor((low + high) / 2);
      const passed = countBusinessDays(
        firstPossible,
        middle + 1,
        orderedObserved,
      );

      if (passed >= n) {
        high = middle;
      } else {
        low = middle + 1;
      }
    }

    return formatOrdinal(low);
  }

  const needed = -n;
  const available = countBusinessDays(0, start, orderedObserved);

  if (needed > available) {
    throwResultOutOfRange();
  }

  let low = 0;
  let high = start - 1;

  while (low < high) {
    const middle = Math.floor((low + high + 1) / 2);
    const passed = countBusinessDays(middle, start, orderedObserved);

    if (passed >= needed) {
      low = middle;
    } else {
      high = middle - 1;
    }
  }

  return formatOrdinal(low);
}

export function businessDaysBetween(start, end, holidays = []) {
  const startOrdinal = parseDateOrdinal(start);
  const endOrdinal = parseDateOrdinal(end);
  const calendar = buildHolidayCalendar(holidays);

  if (startOrdinal === endOrdinal) {
    return 0;
  }

  if (startOrdinal < endOrdinal) {
    return countBusinessDays(
      startOrdinal + 1,
      endOrdinal + 1,
      calendar.orderedObserved,
    );
  }

  const count = countBusinessDays(
    endOrdinal + 1,
    startOrdinal + 1,
    calendar.orderedObserved,
  );

  return count === 0 ? 0 : -count;
}
